import math
from math import comb

def wilson(k, n, z=1.959963984540054):
    if n == 0: return (0.0, 1.0)
    p = k / n
    d = 1 + z*z/n
    c = (p + z*z/(2*n)) / d
    h = z*math.sqrt(p*(1-p)/n + z*z/(4*n*n)) / d
    return (max(0., c-h), min(1., c+h))

def mcnemar_exact_reject(m, p01, psi, alpha):
    # under H1: m discordants ~ Bin(n, psi); b|m ~ Bin(m, p01/psi); two-sided exact binomial test on b vs 0.5
    pass

def power_mcnemar(n, p01, p10, alpha=0.05):
    psi = p01 + p10
    if psi <= 0: return 0.0
    q = p01 / psi
    # precompute critical region for each m
    tot = 0.0
    for m in range(0, n+1):
        pm = comb(n, m) * psi**m * (1-psi)**(n-m)
        if pm < 1e-14: continue
        # exact two-sided binomial test critical region under H0: b~Bin(m,0.5)
        crit = 0
        for b in range(0, m+1):
            # two-sided p-value by doubling the smaller tail (standard McNemar exact)
            lo = sum(comb(m,i)*0.5**m for i in range(0, b+1))
            hi = sum(comb(m,i)*0.5**m for i in range(b, m+1))
            pv = min(1.0, 2*min(lo, hi))
            if pv <= alpha: crit += comb(m,b)*q**b*(1-q)**(m-b)
        tot += pm*crit
    return tot

print("== Potencia McNemar exacto bilateral, alpha=0.05 (n = comportamientos pareados) ==")
print(f"{'ASR_off':>8}{'ASR_on':>8}{'psi':>7}{'OR':>6}", " ".join(f"n={n:<4}" for n in (50,100,150,200,300,500)))
for asr0, asr1, psi in [(0.60,0.40,0.30),(0.55,0.35,0.30),(0.55,0.40,0.25),(0.50,0.35,0.25),(0.70,0.60,0.20),(0.55,0.45,0.15),(0.30,0.20,0.15)]:
    p01 = psi*0.667; p10 = psi*0.333   # 2:1 asymmetry de discordantes = efecto SSP realista
    ps = [power_mcnemar(n, p01, p10) for n in (50,100,150,200,300,500)]
    print(f"{asr0:>8.2f}{asr1:>8.2f}{psi:>7.2f}{p01/max(p10,1e-9):>6.2f}", " ".join(f"{p:5.2f} " for p in ps))

print("\n== Ancho del IC Wilson 95% para ASR por celda ==")
for n in (50,100,200,300,900):
    lo,hi = wilson(int(round(0.55*n)), n)
    print(f"  n={n:>4}  ASR=0.55 -> IC [{lo:.3f},{hi:.3f}]  ancho={hi-lo:.3f}")

print("\n== Efecto de diseno por k=3 generaciones con ICC rho (n_prompts=100) ==")
for rho in (0.0,0.2,0.4,0.6):
    deff = 1 + (3-1)*rho
    print(f"  rho={rho:.1f}  DEFF={deff:.2f}  n_eff={100*3/deff:6.1f} de 300 generaciones")
