models = 3
cells_ssp = 2; family = 2; adapt = 2
K_beh = 100          # comportamientos adversarios
seeds = 3            # semillas de ataque (sufijo/plantilla muestreada)
k_gen = 3            # generaciones por (beh,seed,cond)
n_attack_cells = models*cells_ssp*family*adapt
gen_eval = K_beh*seeds*k_gen*n_attack_cells
out_tok, in_tok = 256, 600      # prompt+suffix+SSP
gen_tokens = gen_eval*out_tok
benign_cells = models*cells_ssp
gen_benign = 100*k_gen*benign_cells          # set benigno, sin ataque
gen_judge = (gen_eval+gen_benign)*1          # 1 pasada de juez
