print(f"TOTAL GPU-h: {gpu_h_eval+gpu_h_gcg:5.1f}")
print(f"Coste variante 'optimizar en los {K_beh} comportamientos': {models*adapt*K_beh*gcg_tok_per_beh/2500/3600:5.1f} GPU-h solo GCG")
