# Presupuesto de pruebas con correccion de Holm y su impacto en potencia
fam = ["token/non-adapt","token/adapt","prompt/non-adapt","prompt/adapt"]
models = ["M1","M2","M3"]
primaria = [(m,f) for m in models for f in fam]
print(f"Principales (modelo x familia): {len(primaria)} pruebas -> Holm alpha_1 = 0.05/{len(primaria)} = {0.05/len(primaria):.4f}")
from math import comb
def power_mcnemar(n,p01,p10,alpha):
    psi=p01+p10; q=p01/psi; tot=0.0
    for m in range(n+1):
        pm=comb(n,m)*psi**m*(1-psi)**(n-m)
        if pm<1e-13: continue
        crit=0.0
        for b in range(m+1):
            lo=sum(comb(m,i)*0.5**m for i in range(b+1)); hi=sum(comb(m,i)*0.5**m for i in range(b,m+1))
            if min(1.0,2*min(lo,hi))<=alpha: crit+=comb(m,b)*q**b*(1-q)**(m-b)
        tot+=pm*crit
    return tot
print("\nPotencia con Holm (alpha_1=0.05/12), psi=0.30, 2:1:")
for n in (100,200,300,520):
    print(f"  n={n:>4}: alpha=0.05 -> {power_mcnemar(n,0.2,0.1,0.05):.2f} | Holm_1 -> {power_mcnemar(n,0.2,0.1,0.05/12):.2f}")
